// Audit observation (re-run on the refreshed 6de59de1 kernel):
// the pinned engine's upstream debug "manual" moves are not filtered by the
// server adapter. Characterization only; admission stays closed.
import assert from 'node:assert/strict';
const A = await import('./packages/engine-adapter/dist/index.js');
let n = 0;
const m = A.createQualificationMatch({ players: ['p1', 'p2'], startTimestamp: 1000 });
const cmd = (actor, move, input = {}) => ({ actor, move, input, timestamp: 2000 + n, expectedRevision: m.status().revision, commandId: 'o' + (n++) });
const chooser = m.status().choosingFirstPlayer;
assert.equal(m.submit(cmd(chooser, 'chooseWhoGoesFirst', { playerId: 'p1' })).accepted, true);
for (const p of ['p1', 'p2']) assert.equal(m.submit(cmd(p, 'alterHand', { cardsToMulligan: [] })).accepted, true);
const drops = m.submit(cmd('p2', 'manualSetInkDrops', { amount: 99 }));
const r = m.submit(cmd('p2', 'manualSetLore', { amount: 20 }));
const status = m.status();
m.dispose();
console.log(JSON.stringify({ observation: 'manual/debug moves submitted by the non-active player through createQualificationMatch on the refreshed kernel', manualSetInkDropsAccepted: drops.accepted, manualSetLoreAccepted: r.accepted, code: r.code, ended: status.ended, winner: status.winner }));
console.log('OBSERVED pre-existing gap: the server adapter forwards upstream manual/debug moves with player authority; PLAY-01 needs a server move allowlist before any real match');
